/**
 * A player's records per tier: best wave, best this cycle, runs started, best coins and cells.
 *
 * Every one of these lists is indexed by tier number, slot 0 empty, which is what
 * `readSaveTierIndexedValues` reads.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readTierRecordsFromSaveRoot
 * depends    src/save/access/values, src/save/tier-records/types
 * used by    src/calculators/specs.generated, src/save/series/read, src/save/tier-records/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { coerceSaveNumber, readSaveTierIndexedValues } from '../access/values'
import type { TierRecordSaveRow, TierRecordsSaveExtract } from './types'

const TIER_RECORD_SAVE_KEYS = {
  highestWave: 'highestWaveThisTier',
  highestWaveThisCycle: 'highestWavePerTierThisCycle',
  roundsStarted: 'roundsStartedThisTier',
  highestCoinsEarned: 'highestCoinsEarnedThisTier',
  highestCellsEarned: 'highestCellsEarnedThisTier',
} as const satisfies Record<Exclude<keyof TierRecordSaveRow, 'tier'>, string>

/** Per-tier records, or null for a save with none of the per-tier lists. */
export function readTierRecordsFromSaveRoot(root: Record<string, unknown> | null): TierRecordsSaveExtract | null {
  if (!root || !Object.values(TIER_RECORD_SAVE_KEYS).some(key => key in root)) return null
  const columns = Object.fromEntries(
    Object.entries(TIER_RECORD_SAVE_KEYS).map(([field, key]) => [field, readSaveTierIndexedValues(root[key])]),
  ) as Record<keyof typeof TIER_RECORD_SAVE_KEYS, Record<number, number>>
  const tierNumbers = new Set<number>()
  for (const column of Object.values(columns)) for (const tier of Object.keys(column)) tierNumbers.add(Number(tier))

  const tiers = [...tierNumbers].sort((a, b) => a - b).map(tier => ({
    tier,
    highestWave: columns.highestWave[tier] ?? null,
    highestWaveThisCycle: columns.highestWaveThisCycle[tier] ?? null,
    roundsStarted: columns.roundsStarted[tier] ?? null,
    highestCoinsEarned: columns.highestCoinsEarned[tier] ?? null,
    highestCellsEarned: columns.highestCellsEarned[tier] ?? null,
  }))
  return { currentTier: coerceSaveNumber(root.currentTier), tiers }
}
